question.answer:
from collections.abc import Iterator


def countdown(start: int) -> Iterator[int]:
    print("countdown is running now")
    value = start
    while value > 0:
        yield value
        value -= 1


def handshake() -> Iterator[str]:
    yield "hello"
    yield "again"
    yield "goodbye"


def letters(word: str) -> Iterator[str]:
    for character in word:
        yield character

