question.answer:
import sys
from collections.abc import Iterator


def squares(limit: int) -> Iterator[int]:
    return (n * n for n in range(limit))


def scaled_total(readings: list[int]) -> int:
    return sum(reading * 10 for reading in readings)


def any_fault(readings: list[int], limit: int) -> bool:
    return any(reading > limit for reading in readings)


def all_safe(readings: list[int], limit: int) -> bool:
    return all(reading <= limit for reading in readings)


def drain_twice(values: Iterator[int]) -> tuple[list[int], list[int]]:
    return list(values), list(values)


def lazy_is_smaller(limit: int) -> bool:
    return sys.getsizeof(n * n for n in range(limit)) < sys.getsizeof([n * n for n in range(limit)])

