question.answer:
from collections.abc import Iterator, Sequence
from itertools import islice

# Supplied type aliases. Use them in your signatures.
Readings = Sequence[tuple[str, int]]
Batches = Sequence[Readings]
Codes = Iterator[str]
Numbers = Iterator[int]
Verdict = tuple[bool, bool]


def faults(readings: Readings) -> Codes:
    for code, value in readings:
        print(f"checking {code}")
        if value > 100:
            yield code


def all_faults(batches: Batches) -> Codes:
    for batch in batches:
        yield from faults(batch)


def verdict(readings: Readings) -> Verdict:
    return all(value <= 100 for code, value in readings), any(value > 100 for code, value in readings)


def first_fault(readings: Readings) -> str | None:
    return next(faults(readings), None)


def stream(start: int) -> Numbers:
    value = start
    while True:
        yield value
        value += 1


def first_five(start: int) -> Numbers:
    return islice(stream(start), 5)


def total(readings: Readings) -> int:
    return sum(value for code, value in readings)
